import { MeshBasicNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;
  const group = new Group();

  // --- Extract config ---
  const pos = config.scenePosition || { x: 0, y: 1.85, z: 0 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };

  // --- Build plane ---
  const geometry = new PlaneGeometry(2.4, 0.6);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });

  const plane = new Mesh(geometry, material);
  plane.position.set(pos.x, pos.y, pos.z);
  plane.rotation.set(rot.x, rot.y, rot.z);
  plane.scale.set(scl.x, scl.y, scl.z);

  // --- Load texture ---
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    tex.colorSpace = 'srgb-linear';
    material.map = tex;
    material.needsUpdate = true;
  });

  group.add(plane);

  // --- Handle text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(i => i.role === 'headline');

  if (headlineItem) {
    const fontSize = headlineItem.typography?.fontSize || 42;
    const textContent = headlineItem.text || 'Atelier Noir — precise · luxury · technical';

    // Create text using font atlas
    const textMesh = ctx.fontAtlas.createText(textContent, {
      fontSize: fontSize * 2.5, // scene unit scaling
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 500,
      letterSpacingPx: 1,
    });

    if (textMesh) {
      textMesh.position.set(0, 0, 0.01); // slightly in front of plane
      textMesh.scale.set(0.004, 0.004, 0.004); // scale down from pixel space
      group.add(textMesh);
    }
  }

  // --- Gradient backdrop plane (as per design doctrine) ---
  const gradientGeometry = new PlaneGeometry(7, 0.8);
  const gradientMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.15,
    depthWrite: false,
  });

  // Create gradient using vertical position
  const uvNode = uv();
  const gradientNode = vec3(
    mix(
      vec3(0.09, 0.04, 0.04), // #0b0b10 with slight red tint
      vec3(0.09, 0.04, 0.04),
      uvNode.y
    )
  );
  gradientMaterial.colorNode = gradientNode;

  const gradientPlane = new Mesh(gradientGeometry, gradientMaterial);
  gradientPlane.position.set(0, 1.85, -0.05);
  group.add(gradientPlane);

  // --- Cleanup ---
  userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    gradientGeometry.dispose();
    gradientMaterial.dispose();
    // Clean up any added children
    group.children.forEach(child => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
